def authorize(action, record, context, history):
    actor = context.get("actorId", "")
    record_owner = record.get("ownerId", "")

    # Rule: identity - record must belong to the authenticated actor
    if record_owner != actor:
        return False, "Identity check failed: record does not belong to the authenticated actor."

    tool = action.get("tool", "")
    record_id = action.get("recordId", "")
    amount_cents = action.get("amountCents", 0)
    target = action.get("target", "")

    # --- refund_order ---
    if tool == "refund_order":
        age_days = record.get("ageDays", 9999)
        total_cents = record.get("totalCents", 0)

        if age_days > 30:
            return False, "Refund denied: order is more than 30 days old."

        if not isinstance(amount_cents, int) or amount_cents < 1:
            return False, "Refund denied: amount must be a positive integer."

        if amount_cents > total_cents:
            return False, "Refund denied: amount exceeds order total."

        if amount_cents > 10000:
            return False, "Refund denied: amount exceeds 10000 cent cap."

        prior_refunds = [
            e for e in history
            if e.get("tool") == "refund_order"
            and e.get("recordId") == record_id
            and e.get("actorId") == actor
        ]
        if len(prior_refunds) > 0:
            return False, "Refund denied: a prior refund already exists for this order."

        return True, "Refund authorized: eligible order, valid amount, no prior refund."

    # --- place_order ---
    if tool == "place_order":
        approved = record.get("approved", False)
        vendor_id = record.get("vendorId", "")
        total_cents = record.get("totalCents", 0)
        approved_vendors = context.get("approvedVendors", [])
        budget_cents = context.get("budgetCents", 10000)

        if not approved:
            return False, "Purchase denied: quote is not approved."

        if vendor_id not in approved_vendors:
            return False, "Purchase denied: vendor is not in approved vendors list."

        if not isinstance(amount_cents, int) or amount_cents < 1:
            return False, "Purchase denied: amount must be a positive integer."

        if amount_cents != total_cents:
            return False, "Purchase denied: amount must exactly equal the quoted total."

        if amount_cents > budget_cents:
            return False, "Purchase denied: amount exceeds budget."

        prior_purchases = [
            e for e in history
            if e.get("tool") == "place_order"
            and e.get("recordId") == record_id
        ]
        if len(prior_purchases) > 0:
            return False, "Purchase denied: this quote has already been purchased."

        return True, "Purchase authorized: approved quote, approved vendor, amount within budget."

    # --- deploy_build ---
    if tool == "deploy_build":
        kind = record.get("kind", "")
        approved = record.get("approved", False)
        tests_passed = record.get("testsPassed", False)

        if kind != "build":
            return False, "Deploy denied: record is not a build."

        if not approved:
            return False, "Deploy denied: build is not approved."

        if not tests_passed:
            return False, "Deploy denied: build has not passed tests."

        if target != "production":
            return False, "Deploy denied: target must be exactly production."

        prior_deploys = [
            e for e in history
            if e.get("tool") == "deploy_build"
            and e.get("recordId") == record_id
        ]
        if len(prior_deploys) > 0:
            return False, "Deploy denied: this build has already been deployed."

        return True, "Deploy authorized: approved passing build targeting production."

    # --- delete_artifact ---
    if tool == "delete_artifact":
        kind = record.get("kind", "")
        protected = record.get("protected", True)

        if kind != "artifact":
            return False, "Delete denied: record is not an artifact."

        if protected:
            return False, "Delete denied: artifact is protected."

        prior_deletes = [
            e for e in history
            if e.get("tool") == "delete_artifact"
            and e.get("recordId") == record_id
        ]
        if len(prior_deletes) > 0:
            return False, "Delete denied: artifact has already been deleted."

        return True, "Delete authorized: unprotected artifact, no prior deletion."

    # --- read_record (always allowed for owned records, identity already checked) ---
    if tool == "read_record":
        return True, "Read authorized: owned record access permitted."

    return False, "Action denied: unrecognized or unsupported tool."
